// Visual baselines of the ORIGINAL UI (frontend at tests/e2e/ORIGINAL_UI_COMMIT).
// Any pixel change fails. Baselines are only (re)generated by the guarded
// update mode of .github/workflows/render-e2e.yml, never in a normal run.
import { test, expect, openRoute, ROUTES } from "../support/test.mjs";

const EXTRA_THEMES = ["light-nord", "light-sakura", "dark-dracula", "dark-cyberpunk", "dark-forest", "dark-oled"];

async function settle(page) {
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(250);
}

test.describe("desktop 1440x900", () => {
  for (const theme of ["light", "dark"]) {
    for (const { route } of ROUTES) {
      test(`${route} - ${theme}`, async ({ page, mockApi }) => {
        await openRoute(page, route, { theme });
        await settle(page);
        await expect(page).toHaveScreenshot(`desktop-${theme}-${route}.png`);
      });
    }
  }

  for (const theme of EXTRA_THEMES) {
    test(`chat - ${theme}`, async ({ page, mockApi }) => {
      await openRoute(page, "chat", { theme });
      await settle(page);
      await expect(page).toHaveScreenshot(`desktop-${theme}-chat.png`);
    });
  }

  test("settings appearance section", async ({ page, mockApi }) => {
    await openRoute(page, "settings", { theme: "light" });
    const appearance = page.getByRole("tab", { name: "Appearance" });
    await appearance.click();
    await settle(page);
    await expect(page).toHaveScreenshot("desktop-light-settings-appearance.png");
  });
});

test.describe("desktop with a loaded text model", () => {
  test.use({ scenario: "model-loaded" });

  test("chat ready", async ({ page, mockApi }) => {
    await openRoute(page, "chat", { theme: "light" });
    await settle(page);
    await expect(page).toHaveScreenshot("desktop-light-chat-model-ready.png");
  });

  test("chat thread after a streamed reply with reasoning", async ({ page, mockApi }) => {
    await openRoute(page, "chat", { theme: "light" });
    await page.getByRole("textbox", { name: "Message" }).fill("Say hello");
    await page.getByRole("button", { name: "Send message" }).click();
    await expect(page.getByText("Hello from the fixture model.")).toBeVisible();
    // The live thread can race (defect D-3: a stale token flush may leave a finished reply
    // showing "Thinking..."). Capture the deterministic saved state instead: reload and
    // reopen the conversation from the sidebar.
    await expect.poll(() => mockApi.conversations.size).toBe(1);
    const saved = [...mockApi.conversations.values()][0];
    await page.goto("/#/chat");
    await page.reload();
    const sidebar = page.getByRole("complementary", { name: "Sidebar" });
    await sidebar.getByRole("button", { name: /^Chats\s*1$/ }).click();
    await sidebar.getByText(saved.title, { exact: true }).click();
    await expect(page.getByText("Hello from the fixture model.")).toBeVisible();
    await settle(page);
    // Elapsed times come from performance.now(), which the frozen clock does not control,
    // and their text width changes the layout. Assert the real format, then normalise only
    // the numbers in those two text elements before capturing.
    // A duration that rounds to zero is omitted by the UI, so both forms are valid.
    await expect(page.locator(".chat-thinking-title")).toHaveText(/^Thought process( \(\d+(\.\d+)?s\))?$/);
    await expect(page.locator(".chat-generation-stats")).toHaveText(/^5 tokens · \d+(\.\d+)? ?(ms|s)$/);
    await page.evaluate(() => {
      const norm = (sel, re, value) => {
        const walker = document.createTreeWalker(document.querySelector(sel), NodeFilter.SHOW_TEXT);
        for (let n = walker.nextNode(); n; n = walker.nextNode()) n.nodeValue = n.nodeValue.replace(re, value);
      };
      norm(".chat-thinking-title", /^Thought process.*$/, "Thought process (0.0s)");
      norm(".chat-generation-stats", /\d+(\.\d+)? ?(ms|s)$/, "40 ms");
    });
    await expect(page).toHaveScreenshot("desktop-light-chat-thread.png");
  });
});

test.describe("mobile 390x844", () => {
  test.use({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
  for (const { route } of ROUTES) {
    test(`${route} - light`, async ({ page, mockApi }) => {
      await openRoute(page, route, { theme: "light" });
      await settle(page);
      await expect(page).toHaveScreenshot(`mobile-light-${route}.png`);
    });
  }

  // D-2: the open sidebar is an overlay drawer at phone width (approved 2026-11-09).
  test("sidebar drawer open - light", async ({ page, mockApi }) => {
    await openRoute(page, "chat", { theme: "light" });
    await page.getByRole("button", { name: "Open sidebar" }).click();
    await page.getByRole("navigation", { name: "Main" }).waitFor();
    await settle(page);
    await expect(page).toHaveScreenshot("mobile-light-sidebar-open.png");
  });
});
